"""MIRABILIA product CM v2 (cut 3 = worn street clip generated by Muse, brief note 2026-11-17 21:24): Van Gogh《Irises》long-sleeve T, 15 s, no narration (ASTRA storyboard, brief 2026-11-17).
White background, black type. The garment shots are composites on the long-tee blank (no worn photos are made)."""
import sys, os, subprocess, math
import numpy as np
from PIL import Image, ImageDraw, ImageFont, ImageFilter

W, H, FPS = 1080, 1920, 30
D = '/tmp/cm/'
CJK = '/usr/share/fonts/opentype/noto/'
def F(name, size): return ImageFont.truetype(CJK + name + '.ttc', size, index=0)
f_txt = F('NotoSansCJK-Bold', 64); f_ser = F('NotoSerifCJK-Bold', 74); f_small = F('NotoSansCJK-Medium', 40)
f_prod = F('NotoSansCJK-Bold', 56); f_price = F('NotoSansCJK-Black', 92); f_ship = F('NotoSansCJK-Bold', 44); f_url = F('NotoSansCJK-Medium', 44)
INK = (17, 17, 17, 255)

def ease(x): x = max(0.0, min(1.0, x)); return x * x * (3 - 2 * x)
def eo(x): x = max(0.0, min(1.0, x)); return 1 - (1 - x) ** 3
def lerp(a, b, k): return a + (b - a) * k

# product image: 2x composite, light background lifted to white so it sits on the white frame
_m = Image.open(D + 'irises-longtee-mockup-2x.jpg').convert('RGB')
_blank = Image.open(D + 'longtee-blank-black.jpg').convert('L').resize(_m.size, Image.LANCZOS)
_bgmask = np.asarray(_blank.point(lambda v: 255 if v > 110 else 0).filter(ImageFilter.GaussianBlur(6))).astype(float)[..., None] / 255
_a = np.asarray(_m).astype(float)
_white = 255 - (212 - _a).clip(0) * 0.6   # paper-grey (~225) -> white, keep the soft shadow
PROD = Image.fromarray((_a * (1 - _bgmask) + _white * _bgmask).clip(0, 255).astype(np.uint8)).convert('RGBA')
PW, PH = PROD.size

LOGO = Image.open('/tmp/iri/mirabilia-logo-black.png').convert('RGBA')
LOGO = LOGO.crop(LOGO.getchannel('A').point(lambda v: 255 if v > 40 else 0).getbbox())
def logo_img(width):
    return LOGO.resize((width, round(LOGO.height * width / LOGO.width)), Image.LANCZOS)
LOGO_S = logo_img(250); LOGO_L = logo_img(560)

BOX = (0, 200, 1080, 1300)               # image area on the white frame
BW, BH = BOX[2] - BOX[0], BOX[3] - BOX[1]; BA = BW / BH

def view(cam, rot=0.0):
    cx, cy, w = cam; h = w / BA
    if rot == 0.0:
        return PROD.transform((BW, BH), Image.EXTENT, (cx - w / 2, cy - h / 2, cx + w / 2, cy + h / 2), Image.BICUBIC, fillcolor=(255, 255, 255, 255))
    # rotate about the view centre: output (x,y) -> source
    s = w / BW; ca, sa = math.cos(rot), math.sin(rot)
    ox, oy = BW / 2, BH / 2
    a_, b_ = s * ca, -s * sa; d_, e_ = s * sa, s * ca
    c_ = cx - a_ * ox - b_ * oy; f_ = cy - d_ * ox - e_ * oy
    return PROD.transform((BW, BH), Image.AFFINE, (a_, b_, c_, d_, e_, f_), Image.BICUBIC, fillcolor=(255, 255, 255, 255))

def keys_at(keys, t):
    if t <= keys[0][0]: return keys[0][1:]
    for (t0, *a), (t1, *b) in zip(keys, keys[1:]):
        if t <= t1:
            k = ease((t - t0) / (t1 - t0)); return tuple(lerp(p, q, k) for p, q in zip(a, b))
    return keys[-1][1:]

# (start, keys(t, cx, cy, w, rot_deg))
CUTS = [
    (0.0, [(0.0, 2080, 960, 240, 0), (0.25, 2075, 962, 250, 0), (1.85, 1928, 1130, 1650, 0)]),               # flower -> it is a shirt
    (1.8, [(1.8, 1920, 1300, 3560, 0), (4.4, 1920, 1300, 3400, 0)]),                                           # the whole long-sleeve
    (4.3, [(4.3, 1700, 1180, 1500, -2.0), (6.4, 2300, 1350, 1600, 1.0), (8.6, 3000, 1700, 1500, 2.5)]),       # along the chest to the sleeve
    (8.5, [(8.5, 1980, 1150, 1450, 0), (11.1, 2210, 1400, 760, 0)]),                                           # into the print and the logo
]
XF = 0.35; T_END = 11.0; T_TOTAL = 15.0
WORN_N = len([f for f in os.listdir(D + 'worn') if f.endswith('.jpg')])
_wc = {}
def worn(t):
    n = min(WORN_N, max(1, int(round((t - 4.3) * 30)) + 1))
    if n not in _wc: _wc.clear(); _wc[n] = Image.open(D + 'worn/%04d.jpg' % n).convert('RGBA')
    return _wc[n]

def shot(t):
    idx = max(i for i, (ts, _) in enumerate(CUTS) if t >= ts)
    def img(i):
        if i == 2: return worn(t)
        cx, cy, w, r = keys_at(CUTS[i][1], t); return view((cx, cy, w), math.radians(r))
    im = img(idx)
    ts = CUTS[idx][0]
    if idx > 0 and t < ts + XF:
        im = Image.blend(img(idx - 1), im, ease((t - ts) / XF))
    return im

_cache = {}
def text_layer(key, lines, font, lh, track=4, fill=INK):
    if key not in _cache:
        im = Image.new('RGBA', (W, lh * len(lines) + 30), (0, 0, 0, 0)); d = ImageDraw.Draw(im)
        for i, l in enumerate(lines):
            ws = [font.getlength(c, features=['palt']) for c in l]; tw = sum(ws) + track * (len(l) - 1)
            x = W / 2 - tw / 2
            for c, w in zip(l, ws):
                d.text((x, 8 + i * lh), c, font=font, fill=fill, features=['palt']); x += w + track
        _cache[key] = im
    return _cache[key]

def put(fr, key, lines, font, lh, y, a, slide=0, track=4):
    if a <= 0: return
    im = text_layer(key, lines, font, lh, track)
    if a < 1: im = im.copy(); im.putalpha(im.getchannel('A').point(lambda v: int(v * a)))
    fr.alpha_composite(im, (0, int(y + slide)))

CAPS = [(0.75, 1.8, ['絵だと思ったら、服だった。'], f_txt), (2.05, 4.3, ['ゴッホ《アイリス》'], f_ser),
        (4.6, 8.5, ['いつもの一着に。'], f_txt), (8.8, 11.0, ['名画を、日常へ。'], f_txt)]

def captions(fr, t):
    for i, (a, b, lines, font) in enumerate(CAPS):
        if a <= t < b:
            k = min(eo((t - a) / 0.3), eo((b - t) / 0.25))
            put(fr, ('cap', i), lines, font, 90, 1380, k, int(10 * (1 - k)))

THUMB = PROD.crop((240, 300, 3600, 2440)).convert('RGB')
THUMB = THUMB.resize((640, round(THUMB.height * 520 / THUMB.width)), Image.LANCZOS).convert('RGBA')

def endcard(t):
    te = t - T_END
    fr = Image.new('RGBA', (W, H), (255, 255, 255, 255))
    def k_(d): return eo((te - d) / 0.45)
    k = k_(0.0); fr.alpha_composite(LOGO_L if k >= 1 else _fade(LOGO_L, k), (int(W / 2 - LOGO_L.width / 2), 300 + int(10 * (1 - k))))
    k = k_(0.2); fr.alpha_composite(_fade(THUMB, k), (int(W / 2 - THUMB.width / 2), 470 + int(10 * (1 - k))))
    y = 470 + THUMB.height + 40
    put(fr, 'prod', ['ロングスリーブTシャツ'], f_prod, 70, y, k_(0.45), int(8 * (1 - k_(0.45))))
    put(fr, 'art', ['ゴッホ《アイリス》'], f_small, 56, y + 80, k_(0.55), 0)
    put(fr, 'price', ['¥11,980'], f_price, 110, y + 160, k_(0.75), int(8 * (1 - k_(0.75))), track=2)
    put(fr, 'ship', ['送料無料'], f_ship, 60, y + 280, k_(0.85), 0)
    put(fr, 'url', ['mirabilia.base.shop'], f_url, 60, y + 360, k_(1.0), 0, track=1)
    if te > 1.0:
        d = ImageDraw.Draw(fr); kk = eo((te - 1.0) / 0.4)
        tw = f_url.getlength('mirabilia.base.shop') + 18
        d.line([(W / 2 - tw / 2 * kk, y + 432), (W / 2 + tw / 2 * kk, y + 432)], fill=INK, width=3)
    return fr

def _fade(im, a):
    if a >= 1: return im
    im = im.copy(); im.putalpha(im.getchannel('A').point(lambda v: int(v * max(0, a)))); return im

def frame_main(t):
    fr = Image.new('RGBA', (W, H), (255, 255, 255, 255))
    fr.alpha_composite(shot(t), (BOX[0], BOX[1]))
    fr.alpha_composite(LOGO_S, (int(W / 2 - LOGO_S.width / 2), 100))
    captions(fr, t)
    return fr

def frame_at(t):
    if t >= T_END:
        fr = endcard(t)
        if t < T_END + 0.4: fr = Image.blend(frame_main(t), fr, ease((t - T_END) / 0.4))
        return fr.convert('RGB')
    return frame_main(t).convert('RGB')

SEGS = [(0.0, 4.0), (4.0, 8.0), (8.0, 11.5), (11.5, 15.0)]
if __name__ == '__main__':
    if sys.argv[1] == 'stills':
        for ts in sys.argv[2:]: frame_at(float(ts)).save(D + 'v2st_%s.png' % ts)
    elif sys.argv[1] == 'seg':
        i = int(sys.argv[2]); a, b = SEGS[i]; tmp = D + 'v2seg%d.tmp.mp4' % i
        p = subprocess.Popen(['ffmpeg', '-y', '-loglevel', 'error', '-f', 'rawvideo', '-pix_fmt', 'rgb24', '-s', '%dx%d' % (W, H),
                              '-r', str(FPS), '-i', '-', '-c:v', 'libx264', '-crf', '18', '-preset', 'veryfast', '-pix_fmt', 'yuv420p', tmp], stdin=subprocess.PIPE)
        for n in range(round(a * FPS), round(b * FPS)): p.stdin.write(frame_at(n / FPS).tobytes())
        p.stdin.close()
        if p.wait() == 0: os.rename(tmp, D + 'v2seg%d.mp4' % i)
        else: sys.exit(1)
